      <section className="mt-6 grid gap-4 xl:grid-cols-3 xl:gap-6">{visibleModules.map((item) => <article key={item.title} className="flex min-w-0 flex-col rounded-2xl bg-white p-5 shadow-[0_1px_3px_rgba(0,0,0,0.06)]"><div className="flex items-start justify-between gap-3"><span className="font-['Manrope:SemiBold',sans-serif] text-xs font-semibold tracking-[0.06em] text-[#63747a]">{item.module}</span><span className={`grid size-8 shrink-0 place-items-center rounded-full ${item.tone}`}><SvgIcon path={item.icon} viewBox={item.viewBox} className="size-4" /></span></div><h2 className="mt-4 font-['Plus_Jakarta_Sans:SemiBold',sans-serif] text-xl font-semibold leading-7">{item.title}</h2><p className="mt-2 flex-1 font-['Manrope:Regular',sans-serif] text-sm leading-5 text-[#3e4941]">{item.description}</p><div className="mt-5 flex items-center justify-between"><span className="inline-flex items-center gap-1 text-xs text-[#536478]"><SvgIcon path={materiPaths.p8e10ae0} viewBox="0 0 13.3333 13.3333" className="size-3.5" />{item.duration}</span><span className={`rounded-full px-2 py-1 font-['Manrope:SemiBold',sans-serif] text-[10px] ${item.tone}`}>{item.status}</span></div><button type="button" className="mt-5 min-h-11 rounded-full bg-[#006d42] px-4 font-['Manrope:SemiBold',sans-serif] text-sm font-semibold text-white transition hover:bg-[#005c38]">{item.action}</button></article>)}</section>
