function KuisKaderScreen({ onBack, onComplete }: { onBack: () => void; onComplete: () => void }) {
  const quizDurationSeconds = 15 * 60; // mock duration; replace with the database-configured duration later.
  const [secondsLeft, setSecondsLeft] = useState(quizDurationSeconds);
  const [questionIndex, setQuestionIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [showSubmitConfirm, setShowSubmitConfirm] = useState(false);
  const questions = [
    { question: "Apa definisi stunting yang paling tepat menurut WHO?", hint: "Pilih satu jawaban yang paling tepat berdasarkan materi Mengenal Stunting yang telah Anda pelajari.", options: ["Anak yang berat badannya kurang dari standar usianya.", "Gangguan pertumbuhan dan perkembangan akibat kekurangan gizi kronis dan infeksi berulang.", "Anak yang lahir dengan kondisi prematur.", "Kondisi anak yang mengalami demam tinggi dan diare."], answer: 1 },
    { question: "Kapan periode 1000 Hari Pertama Kehidupan dimulai?", hint: "Pilih jawaban yang paling tepat.", options: ["Saat anak mulai sekolah.", "Sejak masa kehamilan hingga anak berusia dua tahun.", "Saat bayi lahir hingga usia satu tahun.", "Setelah anak berusia dua tahun."], answer: 1 },
    { question: "Salah satu langkah penting mencegah stunting adalah?", hint: "Ingat kembali materi gizi ibu dan anak.", options: ["Menunda imunisasi anak.", "Memberikan makanan bergizi seimbang dan memantau pertumbuhan.", "Mengurangi kunjungan ke Posyandu.", "Memberikan minuman manis setiap hari."], answer: 1 },
    { question: "Pengukuran panjang badan balita dilakukan dengan?", hint: "Pilih alat dan posisi yang tepat.", options: ["Timbangan dewasa.", "Pita ukur kain biasa.", "Alat ukur panjang badan sesuai usia anak.", "Menggunakan perkiraan orang tua."], answer: 2 },
    { question: "Peran kader dalam pencegahan stunting adalah?", hint: "Pilih peran yang paling sesuai.", options: ["Mencatat, mengedukasi, dan merujuk bila ditemukan risiko.", "Memberikan diagnosis medis sendiri.", "Menggantikan seluruh peran tenaga kesehatan.", "Hanya hadir saat kegiatan besar."], answer: 0 },
  ];
  useEffect(() => { const timer = window.setInterval(() => setSecondsLeft((value) => Math.max(0, value - 1)), 1000); return () => window.clearInterval(timer); }, []);
  const question = questions[questionIndex];
  const selected = answers[questionIndex];
  const isLast = questionIndex === questions.length - 1;
  const formatTime = (seconds: number) => `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
  const next = () => { if (isLast) setShowSubmitConfirm(true); else setQuestionIndex((value) => value + 1); };
  const backQuestion = () => { if (questionIndex === 0) onBack(); else setQuestionIndex((value) => value - 1); };
  const submitQuiz = () => { setShowSubmitConfirm(false); onComplete(); };
  return <main data-reveal-page className="min-h-svh bg-[#f8f9fa] px-5 pb-10 pt-20 text-[#191c1d] sm:px-8 xl:px-10"><header className="fixed inset-x-0 top-0 z-30 border-b border-black/[0.03] bg-[#f8f9fa]/85 backdrop-blur-xl"><div className="mx-auto flex h-16 w-full max-w-6xl items-center justify-between px-2 sm:px-8 xl:px-10"><div className="flex items-center gap-2"><button type="button" onClick={onBack} className="grid size-12 place-items-center rounded-full text-[#191c1d]" aria-label="Kembali"><SvgIcon path={quizPaths.p225a8cc0} viewBox="0 0 11.775 20" className="h-5 w-3" /></button><img src={quizLogo} alt="Centing Raja" className="size-6 rounded-full object-cover" /><span className="font-['Plus_Jakarta_Sans:SemiBold',sans-serif] text-xl font-semibold text-[#006d42]">Kuis Kader</span></div></div></header>
    <section className="relative mx-auto w-full max-w-3xl rounded-2xl bg-white p-5 shadow-[0_6px_24px_rgba(0,0,0,0.06)] sm:p-7 xl:max-w-4xl xl:p-10"><div className="flex items-center justify-between gap-4"><span className="font-['Manrope:SemiBold',sans-serif] text-sm font-semibold text-[#3e4941]">Pertanyaan {questionIndex + 1} dari {questions.length}</span><span className="text-sm font-semibold text-[#006d42]">{Math.round(((questionIndex + 1) / questions.length) * 100)}% Selesai</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-[#e1e3e4]"><div className="h-full rounded-full bg-[#006d42] transition-[width] duration-300" style={{ width: `${((questionIndex + 1) / questions.length) * 100}%` }} /></div><div className="mt-5 flex items-center justify-between gap-4"><span className="grid size-12 place-items-center rounded-full bg-[#e9f7ef] text-[#005c38]"><SvgIcon path={quizPaths.p1a168100} viewBox="0 0 15.8125 16.6667" className="size-6" /></span><button type="button" className="inline-flex min-h-10 items-center gap-2 rounded-full bg-[#e9f7ef] px-3 font-['Manrope:SemiBold',sans-serif] text-sm font-semibold text-[#006d42] shadow-[0_1px_2px_rgba(0,0,0,0.05)]" aria-label="Durasi kuis"><span className="size-2 rounded-full bg-[#006d42]" />{formatTime(secondsLeft)}</button></div><h1 className="mt-5 font-['Plus_Jakarta_Sans:SemiBold',sans-serif] text-xl font-semibold leading-7 sm:text-2xl">{question.question}</h1><p className="mt-3 max-w-2xl text-sm leading-5 text-[#3e4941]">{question.hint}</p><div className="mt-7 space-y-3">{question.options.map((option, index) => <button key={option} type="button" onClick={() => setAnswers((value) => ({ ...value, [questionIndex]: index }))} className={`flex w-full items-center gap-4 rounded-xl border p-4 text-left text-sm leading-5 transition ${selected === index ? "border-[#006d42] bg-[#e9f7ef]" : "border-[#d8dddc] bg-white hover:border-[#006d42]/50"}`}><span className={`grid size-7 shrink-0 place-items-center rounded-full border font-['Manrope:SemiBold',sans-serif] text-xs ${selected === index ? "border-[#006d42] bg-[#006d42] text-white" : "border-[#b8c1bd] text-[#536478]"}`}>{String.fromCharCode(65 + index)}</span>{option}</button>)}</div><div className={`mt-8 flex items-center gap-3 ${questionIndex === 0 ? "justify-end" : "justify-between"}`}>{questionIndex > 0 && <button type="button" onClick={backQuestion} className="inline-flex min-h-12 items-center gap-2 rounded-full border border-[#cfd8d3] bg-white px-5 font-['Manrope:SemiBold',sans-serif] text-sm font-semibold text-[#3e4941] transition hover:border-[#006d42] hover:text-[#006d42]"><SvgIcon path={quizPaths.p225a8cc0} viewBox="0 0 11.775 20" className="h-4 w-2.5" />Kembali</button>}<button type="button" onClick={next} disabled={selected === undefined} className="inline-flex min-h-12 items-center gap-2 rounded-full bg-[#006d42] px-6 font-['Manrope:SemiBold',sans-serif] text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-45">{isLast ? "Selesai" : "Selanjutnya"}<SvgIcon path={quizPaths.p32510800} viewBox="0 0 13.3333 13.3333" className="size-4" /></button></div></section>{showSubmitConfirm && <div className="fixed inset-0 z-50 grid place-items-center bg-black/35 px-5 backdrop-blur-sm" role="dialog" aria-modal="true" aria-labelledby="submit-quiz-title"><section className="w-full max-w-sm rounded-3xl bg-white p-6 text-center shadow-[0_24px_70px_rgba(0,0,0,0.2)] sm:p-8"><span className="mx-auto grid size-14 place-items-center rounded-full bg-[#e9f7ef] text-xl font-bold text-[#006d42]">?</span><h2 id="submit-quiz-title" className="mt-5 font-['Plus_Jakarta_Sans:SemiBold',sans-serif] text-xl font-semibold text-[#191c1d]">Kirim jawaban?</h2><p className="mt-2 font-['Manrope:Regular',sans-serif] text-sm leading-6 text-[#3e4941]">Apakah Anda yakin ingin mengirim jawaban?</p><div className="mt-7 flex gap-3"><button type="button" onClick={() => setShowSubmitConfirm(false)} className="min-h-12 flex-1 rounded-full border border-[#cfd8d3] font-['Manrope:SemiBold',sans-serif] text-sm font-semibold text-[#3e4941]">Batal</button><button type="button" onClick={submitQuiz} className="min-h-12 flex-1 rounded-full bg-[#006d42] font-['Manrope:SemiBold',sans-serif] text-sm font-semibold text-white">Iya, Kirim</button></div></section></div>}</main>;
}

function QuizResultScreen({ onHome, onBack }: { onHome: () => void; onBack: () => void }) {
  const answerSummary = [
    { question: "Ciri-ciri balita stunting yang paling mudah dikenali?", answer: "Jawaban: Tinggi badan lebih pendek dari standar usianya.", correct: true },
    { question: "Usia Emas (Golden Age) pencegahan stunting berada pada rentang?", answer: "Jawaban: 1000 Hari Pertama Kehidupan (HPK).", correct: true },
    { question: "Pemberian ASI Eksklusif dilakukan sampai bayi berusia?", answer: "Jawaban Anda: 4 Bulan", detail: "Benar: 6 Bulan. Setelah 6 bulan, baru diberikan MPASI.", correct: false },
    { question: "Makanan Pendamping ASI (MPASI) yang baik harus mengandung?", answer: "Jawaban: Protein hewani, karbohidrat, dan lemak.", correct: true },
  ];
  return <main data-reveal-page className="min-h-svh bg-[#f8f9fa] pb-28 pt-16 text-[#191c1d]" aria-label="Hasil kuis kader">
    <header className="fixed inset-x-0 top-0 z-30 border-b border-black/[0.03] bg-[#f8f9fa]/85 backdrop-blur-xl"><div className="mx-auto flex h-16 w-full max-w-7xl items-center px-2 sm:px-8 xl:px-10"><button type="button" onClick={onBack} className="grid size-12 place-items-center rounded-full text-[#191c1d]" aria-label="Kembali"><SvgIcon path={resultPaths.p225a8cc0} viewBox="0 0 11.775 20" className="h-5 w-3" /></button><div className="flex items-center gap-2"><img src={resultLogo} alt="Logo Centing Raja" className="size-6 rounded-full object-cover" /><span className="font-['Plus_Jakarta_Sans:SemiBold',sans-serif] text-xl font-semibold text-[#006d42]">Hasil Kuis</span></div></div></header>
    <div className="mx-auto w-full max-w-7xl xl:px-10"><section className="relative overflow-hidden rounded-b-[32px] bg-[#76d69f] px-5 pb-24 pt-6 text-center shadow-[0_1px_2px_rgba(0,0,0,0.05)] sm:px-10 sm:pb-28 xl:rounded-[0_0_44px_44px] xl:pb-32 xl:pt-9"><span aria-hidden="true" className="absolute -right-12 -top-12 size-48 rounded-full bg-[#006d42]/10 blur-[20px]" /><span aria-hidden="true" className="absolute -bottom-10 -left-12 size-36 rounded-full bg-[#d7f0dd]/45 blur-xl" /><div className="relative mx-auto flex max-w-xl flex-col items-center"><div className="relative mb-1 w-32 sm:w-36"><img src={resultMascot} alt="Maskot Centing Raja merayakan hasil kuis" className="w-full object-contain drop-shadow-[0_8px_0_rgba(0,92,56,0.09)]" /><span className="absolute -right-1 top-0 text-xl text-[#e3bf66]">★</span><span className="absolute -left-2 bottom-4 text-xl text-[#e3bf66]">★</span></div><h1 className="font-['Plus_Jakarta_Sans:Bold',sans-serif] text-[26px] font-bold leading-8 text-[#005c38] sm:text-3xl">Luar Biasa, Kader Hebat!</h1><p className="mt-2 max-w-[300px] font-['Manrope:Regular',sans-serif] text-base leading-6 text-[#005c38]/90">Kamu berhasil menyelesaikan kuis.<br />Terus semangat belajar demi anak bangsa!</p></div></section>
      <div className="relative -mt-12 px-4 sm:-mt-14 sm:px-8 xl:-mt-16 xl:px-12"><section className="mx-auto grid max-w-[920px] gap-7 rounded-2xl bg-white p-6 text-center shadow-[0_4px_18px_rgba(0,0,0,0.08)] sm:p-8 xl:grid-cols-[260px_1fr] xl:items-center xl:gap-12 xl:p-10 xl:text-left"><div className="flex flex-col items-center"><p className="font-['Manrope:SemiBold',sans-serif] text-xs font-semibold uppercase tracking-wide text-[#63747a]">Skor Akhir</p><div className="relative mt-4 grid size-32 place-items-center rounded-full border-[8px] border-[#006d42] sm:size-36"><div><strong className="block font-['Plus_Jakarta_Sans:Bold',sans-serif] text-[26px] font-bold leading-none text-[#006d42]">80</strong><span className="mt-1 block font-['Manrope:SemiBold',sans-serif] text-xs text-[#536478]">/ 100</span></div></div><span className="mt-5 inline-flex items-center gap-2 rounded-full bg-[#e9f7ef] px-3 py-1.5 font-['Manrope:SemiBold',sans-serif] text-xs font-semibold text-[#006d42]"><span className="grid size-4 place-items-center rounded-full bg-white"><SvgIcon path={resultPaths.p127da640} viewBox="0 0 13.5833 10.0208" className="h-2.5 w-3 text-[#006d42]" /></span>4 dari 5 Jawaban Benar</span></div><div className="rounded-2xl bg-[#f4fbf6] p-5 text-left xl:p-6"><p className="font-['Manrope:SemiBold',sans-serif] text-xs font-semibold uppercase tracking-[0.12em] text-[#006d42]">Pencapaian Kader</p><h2 className="mt-2 font-['Plus_Jakarta_Sans:SemiBold',sans-serif] text-xl font-semibold text-[#005c38]">Pemahaman Anda sudah sangat baik.</h2><p className="mt-2 font-['Manrope:Regular',sans-serif] text-sm leading-6 text-[#3e4941]">Terus tingkatkan wawasan tentang pencegahan stunting agar pendampingan keluarga di Posyandu semakin optimal.</p></div></section></div>
      <section className="mx-auto max-w-[920px] px-4 pt-7 sm:px-8 xl:px-12 xl:pt-10"><h2 className="font-['Plus_Jakarta_Sans:SemiBold',sans-serif] text-xl font-semibold">Ringkasan Jawaban</h2><div className="mt-3 space-y-3">{answerSummary.map((item) => <article key={item.question} className={`flex gap-3 rounded-xl p-3 shadow-[0_2px_8px_rgba(0,0,0,0.02)] ${item.correct ? "bg-white" : "bg-[#fff4f3]"}`}><span className={`grid size-7 shrink-0 place-items-center rounded-full ${item.correct ? "bg-[#e9f7ef] text-[#006d42]" : "bg-[#ffe2df] text-[#d84747]"}`}><SvgIcon path={item.correct ? resultPaths.p127da640 : resultPaths.p34536fc0} viewBox={item.correct ? "0 0 13.5833 10.0208" : "0 0 11.6667 11.6667"} className="size-3" /></span><div className="min-w-0"><p className="font-['Manrope:Regular',sans-serif] text-sm leading-5 text-[#3e4941]">{item.question}</p><p className={`mt-1 font-['Manrope:SemiBold',sans-serif] text-xs leading-4 ${item.correct ? "text-[#006d42]" : "text-[#d84747]"}`}>{item.answer}</p>{item.detail && <p className="mt-1 font-['Manrope:Regular',sans-serif] text-xs leading-4 text-[#63747a]">{item.detail}</p>}</div></article>)}</div></section>
      <div className="mx-auto max-w-[920px] px-4 pt-10 sm:px-8 xl:px-12"><button type="button" onClick={onHome} className="min-h-12 w-full rounded-full bg-[#007c4a] px-6 font-['Manrope:SemiBold',sans-serif] text-sm font-semibold text-white shadow-[0_5px_12px_rgba(0,109,66,0.20)] transition hover:bg-[#006d42]">Kembali ke Beranda</button></div>
    </div>
  </main>;
}

function SuccessScreen({ onContinue }: { onContinue: () => void }) {
  const confetti = ["left-[12%] top-[19%]", "left-[24%] top-[12%]", "right-[20%] top-[17%]", "right-[11%] top-[30%]", "left-[18%] bottom-[23%]", "right-[18%] bottom-[20%]"];
  return <main data-reveal-page className="relative flex min-h-svh items-center justify-center overflow-hidden bg-[#f8f9fa] px-5 py-12" aria-label="Pendaftaran berhasil">
    <div aria-hidden="true" className="pointer-events-none absolute inset-0"><SuccessGradient /></div>
    <div aria-hidden="true" className="absolute inset-0 bg-[radial-gradient(circle_at_50%_40%,rgba(118,214,159,0.22),transparent_33%)]" />
    {confetti.map((position, index) => <span key={position} aria-hidden="true" className={`success-confetti absolute z-10 size-2 rounded-sm ${position} ${index % 2 ? "bg-[#ffbb02]" : "bg-[#006d42]"}`} style={{ animationDelay: `${index * 110}ms` }} />)}
    <section className="relative z-20 flex w-full max-w-[390px] flex-col items-center text-center lg:max-w-[610px] lg:rounded-[30px] lg:bg-white/70 lg:px-20 lg:py-16 lg:shadow-[0_24px_80px_rgba(0,80,48,0.12)]">
      <div className="success-burst relative grid size-32 place-items-center rounded-full bg-[#e9f7ef] shadow-[0_0_0_18px_rgba(0,109,66,0.05)] lg:size-36">
        <div className="success-check grid size-20 place-items-center rounded-full bg-[#006d42] text-[42px] font-bold text-white shadow-[0_12px_24px_rgba(0,109,66,0.24)]">✓</div>
      </div>
      <p className="success-label mt-10 rounded-full bg-[#e9f7ef] px-3 py-1 font-['Manrope:SemiBold',sans-serif] text-xs font-semibold uppercase tracking-[0.14em] text-[#006d42]">Akun siap digunakan</p>
      <h1 className="success-copy mt-4 font-['Plus_Jakarta_Sans:SemiBold',sans-serif] text-2xl font-semibold leading-8 text-[#191c1d] lg:text-3xl lg:leading-10">Pendaftaran Berhasil!</h1>
      <p className="success-copy mt-3 max-w-md font-['Manrope:Regular',sans-serif] text-base leading-6 text-[#3e4941]">Terima kasih sudah bergabung dengan Centing Raja. Akun Anda berhasil dibuat dan siap menemani tumbuh kembang si kecil.</p>
      <button type="button" onClick={onContinue} className="success-copy mt-10 inline-flex min-h-12 w-full max-w-[320px] items-center justify-center rounded-full bg-[#006d42] px-6 font-['Plus_Jakarta_Sans:SemiBold',sans-serif] text-base font-semibold text-white shadow-[0_6px_16px_rgba(0,109,66,0.22)] transition hover:-translate-y-0.5 hover:bg-[#005b37] active:translate-y-0">Kembali Masuk</button>
    </section>
  </main>;
}

export default function App() {
  const [screen, setScreen] = useState<"loading" | "welcome" | "about" | "guide" | "nakes" | "kader" | "auth" | "login" | "register" | "otp" | "success" | "kader-dashboard" | "materi" | "tasks" | "quiz" | "result">("loading");
  const revealObserver = useRef<IntersectionObserver | null>(null);
  const [verificationPhone, setVerificationPhone] = useState("");

  useEffect(() => { const timer = window.setTimeout(() => setScreen("welcome"), 5000); return () => window.clearTimeout(timer); }, []);

  useEffect(() => {
    revealObserver.current?.disconnect();
    if (screen === "loading" || screen === "welcome" || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

    const elements = Array.from(document.querySelectorAll<HTMLElement>("[data-reveal-page] header, [data-reveal-page] section, [data-reveal-page] article, [data-reveal-page] nav"));
    elements.forEach((element, index) => {
      element.classList.add("scroll-reveal");
      element.style.setProperty("--reveal-delay", `${Math.min(index * 70, 280)}ms`);
    });

    revealObserver.current = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("is-revealed");
          revealObserver.current?.unobserve(entry.target);
        }
      });
    }, { threshold: 0.12, rootMargin: "0px 0px -32px" });

    elements.forEach((element) => revealObserver.current?.observe(element));
    return () => revealObserver.current?.disconnect();
  }, [screen]);
  if (screen === "loading") return <LoadingScreen />;
  if (screen === "welcome") return <WelcomeScreen onComplete={() => setScreen("about")} />;
  if (screen === "about") return <AboutScreen onComplete={() => setScreen("guide")} />;
  if (screen === "guide") return <ParentGuideScreen guideIndex={0} onNext={() => setScreen("nakes")} />;
  if (screen === "nakes") return <ParentGuideScreen nakes guideIndex={1} onNext={() => setScreen("kader")} />;
  if (screen === "kader") return <ParentGuideScreen kader guideIndex={2} onNext={() => setScreen("auth")} />;
  if (screen === "auth") return <AuthScreen onLogin={() => setScreen("login")} onRegister={() => setScreen("register")} />;
  if (screen === "login") return <LoginScreen onBack={() => setScreen("auth")} onLogin={(role) => setScreen(role === "Kader" ? "kader-dashboard" : "auth")} />;
  if (screen === "kader-dashboard") return <KaderDashboard onMaterial={() => setScreen("materi")} onTasks={() => setScreen("tasks")} />;
  if (screen === "tasks") return <TugasBulanIniScreen onHome={() => setScreen("kader-dashboard")} onMaterial={() => setScreen("materi")} />;
  if (screen === "materi") return <MateriKaderScreen onHome={() => setScreen("kader-dashboard")} onStartQuiz={() => setScreen("quiz")} />;
  if (screen === "quiz") return <KuisKaderScreen onBack={() => setScreen("materi")} onComplete={() => setScreen("result")} />;
  if (screen === "result") return <QuizResultScreen onBack={() => setScreen("materi")} onHome={() => setScreen("kader-dashboard")} />;
  if (screen === "otp") return <OtpScreen phone={verificationPhone} onBack={() => setScreen("register")} onVerified={() => setScreen("success")} />;
  if (screen === "success") return <SuccessScreen onContinue={() => setScreen("login")} />;
  return <RegisterScreen onBack={() => setScreen("login")} onReturn={() => setScreen("auth")} onVerify={(phone) => { setVerificationPhone(phone); setScreen("otp"); }} />;
}
